fn vec_len<T>(x: &Vec<T>) -> usize {
    x.len()
}

fn numpy_log10(x: Vec<f32>) -> Vec<f32> {
    // Preallocate output vector with same capacity as input length.
    let n = x.len();
    let mut result = Vec::with_capacity(n);

    // Iterate over the input by index; at each step the partial result
    // length equals the number of processed items, and i never exceeds n.
    let mut i = 0;
    while i < n {
        result.push(x[i].log10());
        i += 1;
    }

    // The resulting vector has exactly the same length as the input.
    result
}

